if(!function_exists('sk1030_table_exists')){
function sk1030_table_exists(string $table): bool { static $c=[];if(isset($c[$table]))return $c[$table];if(!preg_match('/^[A-Za-z][A-Za-z0-9_]{0,63}$/',$table))return false;try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=? LIMIT 1');$q->execute([$table]);return $c[$table]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$table]=false;} }
function sk1030_columns(string $table): array {static $c=[];if(isset($c[$table]))return $c[$table];if(!sk1030_table_exists($table))return $c[$table]=[];try{$q=db()->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$table]);return $c[$table]=array_map('strval',$q->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){return $c[$table]=[];}}
function sk1030_tid(): int {try{if(function_exists('tenant_id'))return max(0,(int)tenant_id());if(function_exists('current_tenant')){$t=current_tenant();return max(0,(int)($t['id']??0));}}catch(Throwable $e){}return 0;}
function sk1030_uid(): int {try{$u=function_exists('current_user')?current_user():null;return max(0,(int)($u['id']??0));}catch(Throwable $e){return 0;}}
function sk1030_visitor_hash(): string {$cookie=(string)($_COOKIE['sk1030_v']??'');if(!preg_match('/^[a-f0-9]{32}$/',$cookie)){$cookie=bin2hex(random_bytes(16));if(!headers_sent())setcookie('sk1030_v',$cookie,['expires'=>time()+31536000,'path'=>'/','secure'=>!empty($_SERVER['HTTPS']),'httponly'=>true,'samesite'=>'Lax']);}return hash('sha256',$cookie.'|'.(string)($_SERVER['REMOTE_ADDR']??''));}
function sk1030_settings(bool $refresh=false): array {static $c=[];$tid=sk1030_tid();if(!$refresh&&isset($c[$tid]))return $c[$tid];$d=['tenant_id'=>$tid,'hub_enabled'=>1,'smart_request_enabled'=>1,'price_compare_enabled'=>1,'nearby_enabled'=>1,'daily_cards_enabled'=>1,'emergency_enabled'=>1,'reminders_enabled'=>1,'lost_found_enabled'=>1,'homepage_section_enabled'=>1,'requests_per_hour'=>5,'offers_per_request'=>8,'nearby_radius_km'=>20,'request_auto_route_limit'=>5];if(!sk1030_table_exists('customer_utility_settings_v1030'))return $c[$tid]=$d;try{$q=db()->prepare('SELECT * FROM customer_utility_settings_v1030 WHERE tenant_id=? LIMIT 1');$q->execute([$tid]);$r=$q->fetch();if(!$r){db()->prepare('INSERT IGNORE INTO customer_utility_settings_v1030(tenant_id) VALUES(?)')->execute([$tid]);$r=[];}return $c[$tid]=array_merge($d,$r?:[]);}catch(Throwable $e){return $c[$tid]=$d;}}
function sk1030_on(string $key): bool {$s=sk1030_settings();$f=$key.'_enabled';return !array_key_exists($f,$s)||(int)$s[$f]===1;}
function sk1030_rate_ok(): bool {if(!sk1030_table_exists('customer_service_requests_v1030'))return true;$s=sk1030_settings();try{$q=db()->prepare('SELECT COUNT(*) FROM customer_service_requests_v1030 WHERE tenant_id=? AND requester_hash=? AND created_at>=DATE_SUB(NOW(),INTERVAL 1 HOUR)');$q->execute([sk1030_tid(),sk1030_visitor_hash()]);return (int)$q->fetchColumn()<max(1,(int)$s['requests_per_hour']);}catch(Throwable $e){return true;}}
function sk1030_daily_cards(int $limit=8): array {if(!sk1030_on('daily_cards')||!sk1030_table_exists('customer_daily_cards_v1030'))return [];try{$q=db()->prepare('SELECT * FROM customer_daily_cards_v1030 WHERE tenant_id=? AND enabled=1 ORDER BY sort_order,id DESC LIMIT '.max(1,min(20,$limit)));$q->execute([sk1030_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_emergency(int $limit=12): array {if(!sk1030_on('emergency')||!sk1030_table_exists('customer_emergency_contacts_v1030'))return [];try{$q=db()->prepare('SELECT * FROM customer_emergency_contacts_v1030 WHERE tenant_id=? AND enabled=1 ORDER BY sort_order,id DESC LIMIT '.max(1,min(30,$limit)));$q->execute([sk1030_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_submit_request(array $d): int {if(!sk1030_on('smart_request'))throw new RuntimeException('Smart requests are disabled.');if(!sk1030_rate_ok())throw new RuntimeException('Too many requests. Please try again later.');$need=trim((string)($d['need_text']??''));$name=trim((string)($d['contact_name']??''));$phone=trim((string)($d['contact_phone']??''));if(mb_strlen($need)<8)throw new InvalidArgumentException('Please describe what you need.');if($name===''||$phone==='')throw new InvalidArgumentException('Name and phone are required.');$category=substr(preg_replace('/[^a-z0-9_.-]/i','',(string)($d['category_key']??'general')),0,60)?:'general';$uid=sk1030_uid();$q=db()->prepare("INSERT INTO customer_service_requests_v1030(tenant_id,user_id,requester_hash,category_key,need_text,budget_min,budget_max,area,contact_name,contact_phone,contact_whatsapp,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,'open',NOW(),NOW())");$q->execute([sk1030_tid(),$uid?:null,sk1030_visitor_hash(),$category,mb_substr($need,0,1500),max(0,(float)($d['budget_min']??0)),max(0,(float)($d['budget_max']??0)),mb_substr(trim((string)($d['area']??'')),0,160),mb_substr($name,0,120),mb_substr($phone,0,50),mb_substr(trim((string)($d['contact_whatsapp']??'')),0,50)]);$id=(int)db()->lastInsertId();sk1030_auto_route($id,$category,$need);return $id;}
function sk1030_auto_route(int $requestId,string $category,string $need=''): int {
 if($requestId<1||!sk1030_table_exists('businesses')||!sk1030_table_exists('customer_request_routes_v1030'))return 0;
 $cfg=sk1030_settings();$limit=max(1,min(12,(int)$cfg['request_auto_route_limit']));$cols=sk1030_columns('businesses');$where=[];$p=[];$tid=sk1030_tid();$join='';
 if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='b.tenant_id=?';$p[]=$tid;}
 if(in_array('status',$cols,true))$where[]="b.status NOT IN ('deleted','inactive','disabled','rejected')";
 $catText=trim(str_replace(['_','-'],' ',$category));$search=[];
 if(sk1030_table_exists('categories')&&in_array('category_id',$cols,true)){$cc=sk1030_columns('categories');$join=' LEFT JOIN categories c ON c.id=b.category_id ';if(in_array('name',$cc,true))$search[]='c.name LIKE ?';if(in_array('slug',$cc,true))$search[]='c.slug LIKE ?';}
 if(in_array('name',$cols,true))$search[]='b.name LIKE ?';if(in_array('description',$cols,true))$search[]='b.description LIKE ?';
 $baseWhere=$where;$baseP=$p;if($search){$where[]='('.implode(' OR ',$search).')';foreach($search as $_)$p[]='%'.$catText.'%';}
 try{
   $order=(in_array('featured',$cols,true)?'b.featured DESC,':'').(in_array('is_featured',$cols,true)?'b.is_featured DESC,':'').' b.id DESC';
   $sql='SELECT DISTINCT b.id FROM businesses b'.$join.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY '.$order.' LIMIT '.$limit;
   $q=db()->prepare($sql);$q->execute($p);$ids=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));
   if(!$ids){$q=db()->prepare('SELECT b.id FROM businesses b'.($baseWhere?' WHERE '.implode(' AND ',$baseWhere):'').' ORDER BY '.$order.' LIMIT '.$limit);$q->execute($baseP);$ids=array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}
   $ins=db()->prepare("INSERT IGNORE INTO customer_request_routes_v1030(tenant_id,request_id,business_id,status,created_at) VALUES(?,?,?,'sent',NOW())");$n=0;foreach($ids as $bid){$ins->execute([sk1030_tid(),$requestId,$bid]);$n+=$ins->rowCount();}return $n;
 }catch(Throwable $e){return 0;}
}
function sk1030_price_compare(string $term,int $limit=16): array {if(!sk1030_on('price_compare')||!sk1030_table_exists('store_products'))return [];$term=trim($term);if(mb_strlen($term)<2)return [];$cols=sk1030_columns('store_products');$title=in_array('title',$cols,true)?'title':(in_array('name',$cols,true)?'name':'');if($title==='')return [];$select='p.*';$where=["p.`$title` LIKE ?"];$p=['%'.$term.'%'];$tid=sk1030_tid();if($tid>0&&in_array('tenant_id',$cols,true)){$where[]='p.tenant_id=?';$p[]=$tid;}if(in_array('status',$cols,true))$where[]="p.status NOT IN ('deleted','inactive','disabled','rejected')";$order=in_array('sale_price',$cols,true)?'COALESCE(NULLIF(p.sale_price,0),p.price) ASC':(in_array('price',$cols,true)?'p.price ASC':'p.id DESC');try{$q=db()->prepare('SELECT '.$select.' FROM store_products p WHERE '.implode(' AND ',$where).' ORDER BY '.$order.' LIMIT '.max(1,min(40,$limit)));$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_nearby(float $lat,float $lng,string $term='',int $limit=12): array {if(!sk1030_on('nearby')||!sk1030_table_exists('businesses'))return [];$tid=sk1030_tid();$bcols=sk1030_columns('businesses');$hasDetails=sk1030_table_exists('business_details');$dcols=$hasDetails?sk1030_columns('business_details'):[];$latCol=in_array('latitude',$bcols,true)?'b.latitude':(in_array('lat',$bcols,true)?'b.lat':null);$lngCol=in_array('longitude',$bcols,true)?'b.longitude':(in_array('lng',$bcols,true)?'b.lng':null);$join='';if((!$latCol||!$lngCol)&&$hasDetails&&in_array('business_id',$dcols,true)){$join=' LEFT JOIN business_details d ON d.business_id=b.id ';$latCol=in_array('latitude',$dcols,true)?'d.latitude':(in_array('lat',$dcols,true)?'d.lat':null);$lngCol=in_array('longitude',$dcols,true)?'d.longitude':(in_array('lng',$dcols,true)?'d.lng':null);}if(!$latCol||!$lngCol)return [];$distance="(6371 * ACOS(LEAST(1,COS(RADIANS(?))*COS(RADIANS($latCol))*COS(RADIANS($lngCol)-RADIANS(?))+SIN(RADIANS(?))*SIN(RADIANS($latCol)))))";$where=["$latCol IS NOT NULL","$lngCol IS NOT NULL"];$p=[$lat,$lng,$lat];if($tid>0&&in_array('tenant_id',$bcols,true)){$where[]='b.tenant_id=?';$p[]=$tid;}if($term!==''&&in_array('name',$bcols,true)){$where[]='b.name LIKE ?';$p[]='%'.mb_substr($term,0,80).'%';}$radius=max(1,min(100,(float)sk1030_settings()['nearby_radius_km']));try{$sql="SELECT b.*,$distance distance_km FROM businesses b $join WHERE ".implode(' AND ',$where)." HAVING distance_km<=? ORDER BY distance_km ASC LIMIT ".max(1,min(30,$limit));$p[]=$radius;$q=db()->prepare($sql);$q->execute($p);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_my_business_ids(int $uid): array {if($uid<1||!sk1030_table_exists('businesses'))return [];$cols=sk1030_columns('businesses');$where=[];$p=[];if(in_array('owner_user_id',$cols,true)){$where[]='owner_user_id=?';$p[]=$uid;}if(in_array('owner_id',$cols,true)){$where[]='owner_id=?';$p[]=$uid;}if(!$where)return [];try{$q=db()->prepare('SELECT id FROM businesses WHERE '.implode(' OR ',$where));$q->execute($p);return array_map('intval',$q->fetchAll(PDO::FETCH_COLUMN));}catch(Throwable $e){return [];}}
function sk1030_save_offer(int $requestId,int $businessId,array $d): int {
 $uid=sk1030_uid();if($uid<1)throw new RuntimeException('Login required.');if(!in_array($businessId,sk1030_my_business_ids($uid),true))throw new RuntimeException('Business access denied.');
 $q=db()->prepare('SELECT 1 FROM customer_request_routes_v1030 WHERE tenant_id=? AND request_id=? AND business_id=? LIMIT 1');$q->execute([sk1030_tid(),$requestId,$businessId]);if(!$q->fetchColumn())throw new RuntimeException('This request was not routed to this business.');
 $existing=db()->prepare('SELECT id FROM customer_request_offers_v1030 WHERE tenant_id=? AND request_id=? AND business_id=? LIMIT 1');$existing->execute([sk1030_tid(),$requestId,$businessId]);$existingId=(int)($existing->fetchColumn()?:0);
 if($existingId<1){$cnt=db()->prepare("SELECT COUNT(*) FROM customer_request_offers_v1030 WHERE tenant_id=? AND request_id=? AND status='active'");$cnt->execute([sk1030_tid(),$requestId]);if((int)$cnt->fetchColumn()>=max(1,(int)sk1030_settings()['offers_per_request']))throw new RuntimeException('This request already has the maximum number of active offers.');}
 $price=max(0,(float)($d['price']??0));$msg=trim((string)($d['message']??''));if($msg===''&&$price<=0)throw new InvalidArgumentException('Add a price or message.');
 $q=db()->prepare("INSERT INTO customer_request_offers_v1030(tenant_id,request_id,business_id,offered_by,price,message,status,created_at,updated_at) VALUES(?,?,?,?,?,?,'active',NOW(),NOW()) ON DUPLICATE KEY UPDATE price=VALUES(price),message=VALUES(message),status='active',updated_at=NOW()");$q->execute([sk1030_tid(),$requestId,$businessId,$uid,$price,mb_substr($msg,0,1000)]);return (int)($existingId?:db()->lastInsertId());
}
function sk1030_save_reminder(array $d): int {$uid=sk1030_uid();if($uid<1)throw new RuntimeException('Login required for reminders.');$provider=trim((string)($d['provider']??''));$label=trim((string)($d['label']??''));if($provider===''||$label==='')throw new InvalidArgumentException('Provider and label are required.');$due=max(1,min(31,(int)($d['due_day']??1)));$days=max(0,min(15,(int)($d['reminder_days']??3)));$q=db()->prepare('INSERT INTO customer_saved_utilities_v1030(tenant_id,user_id,provider,label,reference_last4,due_day,reminder_days,enabled,created_at,updated_at) VALUES(?,?,?,?,?,?,?,1,NOW(),NOW())');$q->execute([sk1030_tid(),$uid,mb_substr($provider,0,100),mb_substr($label,0,120),preg_replace('/\D+/','',(string)($d['reference_last4']??''))?:null,$due,$days]);return (int)db()->lastInsertId();}
function sk1030_reminders(): array {$uid=sk1030_uid();if($uid<1||!sk1030_table_exists('customer_saved_utilities_v1030'))return [];try{$q=db()->prepare('SELECT * FROM customer_saved_utilities_v1030 WHERE tenant_id=? AND user_id=? AND enabled=1 ORDER BY due_day,id');$q->execute([sk1030_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_submit_lost_found(array $d): int {if(!sk1030_on('lost_found'))throw new RuntimeException('Lost & Found is disabled.');$type=in_array((string)($d['item_type']??''),['lost','found'],true)?(string)$d['item_type']:'lost';$title=trim((string)($d['title']??''));$desc=trim((string)($d['description']??''));$phone=trim((string)($d['contact_phone']??''));if($title===''||$desc==='')throw new InvalidArgumentException('Title and description are required.');$q=db()->prepare("INSERT INTO customer_lost_found_v1030(tenant_id,user_id,requester_hash,item_type,title,description,area,contact_phone,public_contact,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,'pending',NOW(),NOW())");$q->execute([sk1030_tid(),sk1030_uid()?:null,sk1030_visitor_hash(),$type,mb_substr($title,0,160),mb_substr($desc,0,1200),mb_substr(trim((string)($d['area']??'')),0,160),mb_substr($phone,0,50),!empty($d['public_contact'])?1:0]);return (int)db()->lastInsertId();}
function sk1030_public_lost_found(int $limit=12): array {if(!sk1030_on('lost_found')||!sk1030_table_exists('customer_lost_found_v1030'))return [];try{$q=db()->prepare("SELECT * FROM customer_lost_found_v1030 WHERE tenant_id=? AND status='approved' ORDER BY id DESC LIMIT ".max(1,min(30,$limit)));$q->execute([sk1030_tid()]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_alerts(int $limit=12): array {$uid=sk1030_uid();if($uid<1||!sk1030_table_exists('customer_utility_alerts_v1030'))return [];try{$q=db()->prepare('SELECT * FROM customer_utility_alerts_v1030 WHERE tenant_id=? AND user_id=? ORDER BY id DESC LIMIT '.max(1,min(30,$limit)));$q->execute([sk1030_tid(),$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1030_my_requests(int $limit=12): array {if(!sk1030_table_exists('customer_service_requests_v1030'))return [];$tid=sk1030_tid();$uid=sk1030_uid();try{if($uid>0){$q=db()->prepare('SELECT * FROM customer_service_requests_v1030 WHERE tenant_id=? AND user_id=? ORDER BY id DESC LIMIT '.max(1,min(30,$limit)));$q->execute([$tid,$uid]);}else{$q=db()->prepare('SELECT * FROM customer_service_requests_v1030 WHERE tenant_id=? AND requester_hash=? ORDER BY id DESC LIMIT '.max(1,min(30,$limit)));$q->execute([$tid,sk1030_visitor_hash()]);}$rows=$q->fetchAll()?:[];if(!$rows)return [];$ids=array_map(fn($r)=>(int)$r['id'],$rows);$ph=implode(',',array_fill(0,count($ids),'?'));$offers=[];$sql="SELECT o.*,b.name business_name,b.phone business_phone FROM customer_request_offers_v1030 o LEFT JOIN businesses b ON b.id=o.business_id WHERE o.tenant_id=? AND o.request_id IN ($ph) AND o.status='active' ORDER BY o.price ASC,o.id DESC";$st=db()->prepare($sql);$st->execute(array_merge([$tid],$ids));foreach($st->fetchAll()?:[] as $o)$offers[(int)$o['request_id']][]=$o;foreach($rows as &$r)$r['_offers']=$offers[(int)$r['id']]??[];unset($r);return $rows;}catch(Throwable $e){return [];}}
function sk1030_stats(): array {$tid=sk1030_tid();$o=['open_requests'=>0,'offers'=>0,'reminders'=>0,'pending_lost_found'=>0];foreach(['open_requests'=>['customer_service_requests_v1030',"status='open'"],'offers'=>['customer_request_offers_v1030',"status='active'"],'reminders'=>['customer_saved_utilities_v1030','enabled=1'],'pending_lost_found'=>['customer_lost_found_v1030',"status='pending'"]] as $k=>$x){if(!sk1030_table_exists($x[0]))continue;try{$q=db()->prepare('SELECT COUNT(*) FROM `'.$x[0].'` WHERE tenant_id=? AND '.$x[1]);$q->execute([$tid]);$o[$k]=(int)$q->fetchColumn();}catch(Throwable $e){}}return $o;}
